-- We use the universal property of the free product Monoid.Coprod G H
-- We need homomorphisms from ↑G and ↑H to ↑(coprod G H)
-- These come from coprod.inl and coprod.inr

def morphism_to_coprod : GrpCat.of (Monoid.Coprod G H) ⟶ coprod G H :=
  GrpCat.ofHom (Monoid.Coprod.lift (coprod.inl.hom) (coprod.inr.hom))","subgoal_id":"sg1","purpose":"subgoal"}

